"""Independent accepted literals, never generated by the production encoder."""

import json
from datetime import datetime
from pathlib import Path

import pytest

from custom_components.adjustable_bed.profiles import dynasty_base_a as app

VECTORS = json.loads((Path(__file__).parent / "fixtures/dynasty_base_a/vectors.json").read_text())


@pytest.mark.parametrize("row", VECTORS, ids=lambda row: row["id"])
def test_frozen_literal(row):
    values = row["inputs"]
    if "mask" in values:
        actual = app.frame(row["protocol"].lower(), values["mask"])
    elif "days" in values:
        actual = app.alarm(values["hour"], values["minute"], values["days"], values["mode"])
    else:
        actual = app.codec.clock(
            datetime(
                values["year"],
                values["month_zero"] + 1,
                values["day"],
                values["hour"],
                values["minute"],
                values["second"],
            )
        )
    assert actual == bytes.fromhex(row["expected_bytes"])
